param([Parameter(Mandatory=$true)][string]$PackageRoot)
$ErrorActionPreference='Stop'
$repo=Split-Path -Parent $PSScriptRoot;$out=Join-Path $PSScriptRoot ('output\follow-'+[guid]::NewGuid().ToString('N'));$null=New-Item -ItemType Directory -Path $out
$files=@('Manager.cs','IconAssets.cs','WallpaperLibrary.cs','GalleryControls.cs','GalleryManager.cs','MediaPreviewJob.cs','SoftwareUpdate.cs','ManagerUpdates.cs','ManagerPetAppearance.cs','ManagerFollow.cs','CodexFollow.cs','PetCardPalette.cs','DailyUpdates.cs','CloudPets.cs','BuiltinDownloads.cs','CompanionCore.cs','WindowResize.cs','CompanionBehavior.cs','CompanionVideo.cs','CompanionOverlay.cs','CompanionSettings.cs','CompanionQuota.cs','CompanionWindow.cs','CompanionPage.cs','DouyinSpark.cs','DouyinAccessibility.cs','DouyinWorker.cs','DouyinLauncher.cs','DouyinNativeUia.cs','CompanionAutomation.cs','ManagerDouyin.cs','CompanionActivity.cs','CompanionBailong.cs','CompanionTokens.cs','HubPopupMenu.cs')|ForEach-Object{Join-Path $repo ('source\'+$_)}
$exe=Join-Path $PackageRoot 'FollowAppearanceTests.exe';$report=Join-Path $out 'result.json'
& (Join-Path $env:WINDIR 'Microsoft.NET\Framework64\v4.0.30319\csc.exe') /nologo /target:winexe /main:FollowAppearanceTests /platform:x64 /codepage:65001 ("/out:$exe") /r:System.Windows.Forms.dll /r:System.Drawing.dll /r:System.Web.Extensions.dll /r:Accessibility.dll /r:UIAutomationClient.dll /r:UIAutomationTypes.dll /r:WindowsBase.dll /r:"$repo\source\assets\windows\Interop.UIAutomationClient.dll" /resource:"$repo\source\assets\windows\Interop.UIAutomationClient.dll,CodexHub.UIAutomationInterop" "/lib:$env:WINDIR\Microsoft.NET\Framework64\v4.0.30319\WPF" /r:System.IO.Compression.dll /r:System.IO.Compression.FileSystem.dll $files (Join-Path $PSScriptRoot 'FollowAppearanceTests.cs')
if($LASTEXITCODE -ne 0){throw 'Follow/appearance tests failed to compile'}
try{$p=Start-Process -FilePath $exe -ArgumentList ('"'+[IO.Path]::GetFullPath($PackageRoot)+'" "'+$report+'"') -WindowStyle Hidden -PassThru;if(-not $p.WaitForExit(30000)){throw 'Follow/appearance tests timed out'};$data=Get-Content -LiteralPath $report -Raw|ConvertFrom-Json;if($p.ExitCode -ne 0 -or -not $data.pass){throw ($data|ConvertTo-Json -Compress)};$data|ConvertTo-Json -Compress;Write-Output ('Report: '+$report)}finally{Remove-Item -LiteralPath $exe -Force -ErrorAction SilentlyContinue}
